class Grid {
  constructor(w, h, spacing, margin) {
    this.w = w;
    this.h = h;
    this.spacing = spacing;
    this.margin = margin;
    this.center = createVector(w / 2, h / 2);
    this.maxDist = dist(0, 0, this.center.x, this.center.y);
  }

  sgn(val) {
    if (val == 0) {
      return 0;
    }
    return val / abs(val);
  }

  superellipse(v, sc, a = 1, b = 1, m = 6) {
    push();
    beginShape();
    for (let theta = 0; theta < TWO_PI; theta += 0.05) {
      let na = 2 / m;
      let x = v.x + sc * pow(abs(cos(theta)), na) * a * this.sgn(cos(theta));
      let y = v.y + sc * pow(abs(sin(theta)), na) * b * this.sgn(sin(theta));
      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }

  display(frameCount) {
    for (let x = this.margin; x < this.w - this.margin; x += this.spacing) {
      for (let y = this.margin; y < this.h - this.margin; y += this.spacing) {
        let d = dist(x, y, this.center.x, this.center.y);
        let norm = (d / this.maxDist) * 0.5 + 0.5;
		  let a = norm * 2 * PI * radians(frameCount);
        let c1 = color(91, 95, 151);
        let c2 = color(255, 107, 108);
				noStroke()
        let c = lerpColor(c1, c2, d / this.maxDist);
        fill(c);
        let scale = map(
          sin(a),
          -1,
          1,
          0.25,
          0.45
        );
        let w = this.spacing * scale;

        let v = createVector(x+w, y + w/2);
        let m = map(sin(a), -1, 1, 0.6, 6);
        this.superellipse(v, w, 1, 1, m);
      }
    }
  }
}


