/* Created for #WCCChallenge "Waves"

Grid with superellipses morphing between an astroid shape and rounded squares.

References: 

Daniel Shiffman--Superellipse Cdoing Challenge: https://thecodingtrain.com/challenges/19-superellipse
Pat Vira--Oscilating Wave Pattern: https: //www.youtube.com/watch?v=MpDUW_bvihE
*/

var grid, canvas, canvasSize, s;
var fullScreen = false;

var margin = 20;

function setup() {
	if (canvas) canvas.remove();
	if (!fullScreen) {
		canvasSize = max(windowWidth, windowHeight);
		canvas = createCanvas(canvasSize, canvasSize);
		s = floor((canvasSize - margin * 2) * 0.04)

	} else {
		canvas = createCanvas(windowWidth, windowHeight);
		s = floor((canvasSize - margin * 2) * 0.05)
	}

	canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);

	// Add new grid
	grid = new Grid(width, height, s, margin);
}

function draw() {
	background(255, 255, 251);
	// background(0);
	grid.display(frameCount);
}

function mousePressed() {
	if (!fullScreen) {
		fullScreen = true;
	} else {
		fullScreen = false;
	}
	setup()
}

function windowResized() {
	setup()
}
